SELECT CASE WHEN YEAR(a.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(a.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, MIN(t.amount) AS min_amount FROM transactions t RIGHT JOIN accounts a ON t.account_id = a.id WHERE t.merchant = 'Starbucks' GROUP BY CASE WHEN YEAR(a.opened_date) < 2024 THEN 'before_2024' WHEN YEAR(a.opened_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY 1;
